 if(d.teamApplyReplace){const target=teamSettings.replace;if(!target||target===teamLeader)return;rememberTeam();selectedTeam=selectedTeam.map(x=>x===target?d.teamApplyReplace:x);teamSettings.locked=teamSettings.locked.filter(x=>x!==target);teamSettings.replace='';teamVariants=[];saveTeamState();renderTeam();return;}
 if(d.teamPair){const [i,j]=d.teamPair.split(',').map(Number),cards=teamCards(),a=cards[i],c=cards[j];if(a&&c)$('#teamPairInfo').textContent=a.name+' + '+c.name+' : '+(TE.links(a,c).join(' · ')||'Aucun lien activable (les cartes de même nom ne se lient pas).');return;}
 if(d.teamVariant!==undefined){const cards=teamVariants[Number(d.teamVariant)];if(cards){rememberTeam();selectedTeam=[...cards];saveTeamState();renderTeam();}return;}
 if(d.teamLoad){cancelTeamJob();const s=teamSaved().find(x=>x.id===d.teamLoad);if(s){rememberTeam();const owned=teamAvailableIds(s.settings);selectedTeam=[...new Set(s.cards.filter(id=>owned.has(id)))];teamLeader=owned.has(s.leader)?s.leader:'';teamSettings.leadCategory='';Object.assign(teamSettings,s.settings);teamSettings.savedSource=s.id;normalizeTeamSettings();teamVariants=[];saveTeamState();renderTeam();}return;}
 if(d.teamDelete){storageWrite('dokkanos-saved-teams-v2',JSON.stringify(teamSaved().filter(x=>x.id!==d.teamDelete)));renderTeam();return;}
 if(d.teamAction==='save'){if(!selectedTeam.length)return;const name=$('#teamName').value.trim()||teamSaved().find(s=>s.id===teamSettings.savedSource)?.name||'Mon équipe',saved=teamSaved();const source=saved.find(s=>s.id===teamSettings.savedSource),next={id:Date.now()+'-'+Math.random().toString(36).slice(2,8),name,cards:[...selectedTeam],leader:teamLeader,settings:JSON.parse(JSON.stringify(teamSettings))};if(window.DokkanBattles)window.DokkanBattles.enrich(next,source);saved.push(next);teamSettings.savedSource=next.id;teamSaveSettings();storageWrite('dokkanos-saved-teams-v2',JSON.stringify(saved));renderTeam();}
 if(d.teamAction==='results'){const row=[...document.querySelectorAll('[data-battle-form]')].find(f=>f.dataset.battleForm===teamSettings.savedSource)?.closest('.battle-saved');if(row){row.querySelector('details').open=true;row.scrollIntoView({behavior:'smooth',block:'start'});}else $('#teamSaved')?.scrollIntoView({behavior:'smooth',block:'start'});return;}
