 if(d.teamAction==='restoreExcluded'){teamSettings.excluded=[];teamSaveSettings();renderTeam();}
 if(d.teamAction==='undo'&&teamUndo){cancelTeamJob();const previous=teamUndo;teamUndo=null;selectedTeam=previous.cards;teamLeader=previous.leader;teamSettings=previous.settings;normalizeTeamSettings();teamVariants=[];saveTeamState();renderTeam();}
 if(d.teamAction==='openEvent'){eventSettings.selected=teamSettings.event;eventSettings.stage=teamSettings.eventStage;eventSettings.missions=[...teamSettings.eventMissions];eventSave();switchView('events');return;}
